import subprocess
import os
import glob
import time
def task_func(test_dir):
    if not os.path.isdir(test_dir):
        raise OSError("Invalid directory")

    python_files = glob.glob(os.path.join(test_dir, "*.py"))
    execution_times = {}

    for script in python_files:
        start_time = time.time()
        try:
            subprocess.run(["python", script], check=True)
        except Exception as e:
            raise RuntimeError(f"Failed to execute {script}: {e}")
        end_time = time.time()
        execution_times[os.path.basename(script)] = end_time - start_time

    return execution_times

